async ({ shell: { execFile } }) => {
  await new Promise((r) => setTimeout(r, 10000));
  const list = await execFile("gh", ["run", "list", "--workflow", "release.yml", "--limit", "1", "--json", "databaseId,headBranch,status"]);
  const id = JSON.parse(list.stdout)[0]?.databaseId;
  const w = await execFile("gh", ["run", "watch", String(id), "--exit-status", "--interval", "10"], { timeoutMs: 240000 });
  const rel = await execFile("gh", ["release", "view", "v2.5.5", "--json", "isDraft,url,body"]);
  const v2 = await execFile("git", ["ls-remote", "origin", "refs/tags/v2", "refs/tags/v2^{}", "refs/tags/v2.5.5^{}"]);
  return { run: list.stdout, code: w.code, tail: w.stdout.slice(-600), rel: rel.stdout.slice(0, 2500), v2: v2.stdout };
}
